    rabbitAdmin.deleteQueue("testChannel");
    rabbitAdmin.deleteExchange("si.fanout.testChannel");
}

@Test
public void extractPayloadTests() {
    Foo foo = new Foo("bar");
    Message<?> message = MessageBuilder.withPayload(foo).setHeader("baz", "qux").build();
    this.pollableWithEP.send(message);
    Message<?> received = this.pollableWithEP.receive(10000);
    assertThat(received).isNotNull();
    assertThat(received.getPayload()).isEqualTo(foo);
    assertThat(received.getHeaders().get("baz")).isEqualTo("qux");
    this.withEP.send(message);
    received = this.out.receive(10000);
    assertThat(received).isNotNull();
    assertThat(received.getPayload()).isEqualTo(foo);
    assertThat(received.getHeaders().get("baz")).isEqualTo("qux");
    this.pubSubWithEP.send(message);
    received = this.out.receive(10000);
    assertThat(received).isNotNull();
    assertThat(received.getPayload()).isEqualTo(foo);
    assertThat(received.getHeaders().get("baz")).isEqualTo("qux");
    assertThat(TestUtils.getPropertyValue(this.pollableWithEP, "inboundHeaderMapper")).isSameAs(this.mapperIn);
    assertThat(TestUtils.getPropertyValue(this.pollableWithEP, "outboundHeaderMapper")).isSameAs(this.mapperOut);
}

@Test
public void messageConversionTests() {
    RabbitTemplate amqpTemplate = new RabbitTemplate(this.connectionFactory);
    MessageConverter messageConverter = mock(MessageConverter.class);
    amqpTemplate.setMessageConverter(messageConverter);
    PointToPointSubscribableAmqpChannel channel = new PointToPointSubscribableAmqpChannel("testConvertFail", new SimpleMessageListenerContainer(this.connectionFactory), amqpTemplate);
    channel.setBeanFactory(mock());
    channel.afterPropertiesSet();
    MessageListener listener = TestUtils.getPropertyValue(channel, "container.messageListener", MessageListener.class);
    willThrow(new MessageConversionException("foo", new IllegalStateException("bar"))).given(messageConverter).fromMessage(any(org.springframework.amqp.core.Message.class));
    assertThatExceptionOfType(MessageConversionException.class).isThrownBy(() -> listener.onMessage(mock(org.springframework.amqp.core.Message.class))).withCauseInstanceOf(IllegalStateException.class);
}

@Test
public void testPtP() throws Exception {
    final Channel channel = mock();
    DeclareOk declareOk = mock();
    when(declareOk.getQueue()).thenReturn("noSubscribersChannel");
    when(channel.queueDeclare(anyString(), anyBoolean(), anyBoolean(), anyBoolean(), isNull())).thenReturn(declareOk);
    Connection connection = mock(Connection.class);
    doAnswer(invocation -> channel).when(connection).createChannel(anyBoolean());
    ConnectionFactory connectionFactory = mock(ConnectionFactory.class);
    when(connectionFactory.createConnection()).thenReturn(connection);
    SimpleMessageListenerContainer container = new SimpleMessageListenerContainer();
    container.setConnectionFactory(connectionFactory);
    AmqpTemplate amqpTemplate = mock(AmqpTemplate.class);
    PointToPointSubscribableAmqpChannel amqpChannel = new PointToPointSubscribableAmqpChannel("noSubscribersChannel", container, amqpTemplate);
    amqpChannel.setBeanName("noSubscribersChannel");
    amqpChannel.setBeanFactory(mock(BeanFactory.class));
    amqpChannel.afterPropertiesSet();
    MessageListener listener = container.getMessageListener();
    assertThatExceptionOfType(ListenerExecutionFailedException.class).isThrownBy(() -> listener.onMessage(new Message("Hello world!".getBytes()))).withMessageContaining("Dispatcher has no subscribers for amqp-channel 'noSubscribersChannel'.");
}

