@Test
void testDefaultAggregation() {
    QueueChannel resultChannel = new QueueChannel();
    FluxAggregatorMessageHandler fluxAggregatorMessageHandler = new FluxAggregatorMessageHandler();
    fluxAggregatorMessageHandler.setOutputChannel(resultChannel);
    fluxAggregatorMessageHandler.start();
    for (int i = 0; i < 20; i++) {
        Message<?> messageToAggregate = MessageBuilder.withPayload("" + i).setCorrelationId(i % 2).setSequenceSize(10).build();
        fluxAggregatorMessageHandler.handleMessage(messageToAggregate);
    }
    Message<?> result = resultChannel.receive(10_000);
    assertThat(result).isNotNull().extracting(Message::getHeaders).satisfies((headers) -> assertThat(headers).containsEntry(IntegrationMessageHeaderAccessor.CORRELATION_ID, 0));
    Object payload = result.getPayload();
    assertThat(payload).isInstanceOf(Flux.class);
    Flux<Message<?>> window = (Flux<Message<?>>) payload;
    StepVerifier.create(window.map(Message::getPayload).cast(String.class)).expectNextSequence(IntStream.iterate(0, i -> i + 2).limit(10).mapToObj(Objects::toString).collect(Collectors.toList())).verifyComplete();
    result = resultChannel.receive(10_000);
    assertThat(result).isNotNull().extracting(Message::getHeaders).satisfies((headers) -> assertThat(headers).containsEntry(IntegrationMessageHeaderAccessor.CORRELATION_ID, 1));
    payload = result.getPayload();
    window = (Flux<Message<?>>) payload;
    StepVerifier.create(window.map(Message::getPayload).cast(String.class)).expectNextSequence(IntStream.iterate(1, i -> i + 2).limit(10).mapToObj(Objects::toString).collect(Collectors.toList())).verifyComplete();
    fluxAggregatorMessageHandler.stop();
}

