    assertThat(result).isNotNull();
    Flux<Message<?>> window = (Flux<Message<?>>) result.getPayload();
    List<Integer> messageList = window.map(Message::getPayload).cast(Integer.class).collectList().block(Duration.ofSeconds(10));
    assertThat(messageList).isNotEmpty().hasSizeLessThan(10).contains(0, 1);
    result = resultChannel.receive(10_000);
    assertThat(result).isNotNull();
    window = (Flux<Message<?>>) result.getPayload();
    messageList = window.map(Message::getPayload).cast(Integer.class).collectList().block(Duration.ofSeconds(10));
    assertThat(messageList).isNotEmpty().hasSizeLessThan(10).doesNotContain(0, 1);
    fluxAggregatorMessageHandler.stop();
    executorService.shutdown();
}

