@Test
public void validateSequenceSizeHasNoAffectCustomCorrelator() throws Exception {
    CountDownLatch latch = new CountDownLatch(1800);
    for (int i = 0; i < 600; i++) {
        final int counter = i;
        this.executor.execute(() -> {
            this.inputChannel.send(MessageBuilder.withPayload("foo").setHeader("correlation", "foo" + counter).build());
            latch.countDown();
        });
        this.executor.execute(() -> {
            this.inputChannel.send(MessageBuilder.withPayload("bar").setHeader("correlation", "foo" + counter).build());
            latch.countDown();
        });
        this.executor.execute(() -> {
            this.inputChannel.send(MessageBuilder.withPayload("baz").setHeader("correlation", "foo" + counter).build());
            latch.countDown();
        });
    }
    assertThat(latch.await(120, TimeUnit.SECONDS)).as("Sends failed to complete: " + latch.getCount() + " remain").isTrue();
    Message<?> message = this.resultChannel.receive(1000);
    int counter = 0;
    while (message != null) {
        counter++;
        message = this.resultChannel.receive(1000);
    }
    assertThat(counter).isEqualTo(600);
}

@Test
public void validateSequenceSizeHasNoAffectWithSplitter() throws Exception {
    final CountDownLatch latch = new CountDownLatch(1800);
    for (int i = 0; i < 600; i++) {
        this.executor.execute(() -> {
            this.inChannel.send(MessageBuilder.withPayload(new Integer[] { 1, 2, 3, 4, 5, 6, 7, 8 }).build());
            latch.countDown();
        });
        executor.execute(() -> {
            this.inChannel.send(MessageBuilder.withPayload(new Integer[] { 9, 10, 11, 12, 13, 14, 15, 16 }).build());
            latch.countDown();
        });
        executor.execute(() -> {
            this.inChannel.send(MessageBuilder.withPayload(new Integer[] { 17, 18, 19, 20, 21, 22, 23, 24 }).build());
            latch.countDown();
        });
    }
    assertThat(latch.await(60, TimeUnit.SECONDS)).as("Sends failed to complete: " + latch.getCount() + " remain").isTrue();
    Message<?> message = this.resultChannel.receive(1000);
    int counter = 0;
    while (message != null && ++counter < 7200) {
        message = this.resultChannel.receive(1000);
    }
    assertThat(counter).isEqualTo(7200);
}

