@Test
void testBackpressureWithSubscribableChannel() {
    Disposable.Composite compositeDisposable = Disposables.composite();
    try {
        DirectChannel channel = new DirectChannel();
        int initialRequest = 10;
        StepVerifier.create(IntegrationReactiveUtils.messageChannelToFlux(channel), initialRequest).expectSubscription().then(() -> {
            compositeDisposable.add(SCHEDULER.schedule(() -> {
                while (true) {
                    if (channel.getSubscriberCount() > 0) {
                        channel.send(new GenericMessage<>("foo"));
                    }
                }
            }));
        }).expectNextCount(initialRequest).expectNoEvent(Duration.ofMillis(100)).thenCancel().verify(Duration.ofSeconds(1));
    } finally {
        compositeDisposable.dispose();
    }
}

@Test
void testOverproducingWithSubscribableChannel() {
    DirectChannel channel = new DirectChannel();
    Disposable.Composite compositeDisposable = Disposables.composite();
    AtomicInteger sendCount = new AtomicInteger();
    try {
        int initialRequest = 10;
        StepVerifier.create(IntegrationReactiveUtils.messageChannelToFlux(channel), initialRequest).expectSubscription().then(() -> compositeDisposable.add(SCHEDULER.schedule(() -> {
            while (true) {
                if (channel.getSubscriberCount() > 0) {
                    channel.send(new GenericMessage<>("foo"));
                    sendCount.incrementAndGet();
                }
            }
        }))).expectNextCount(initialRequest).thenAwait(Duration.ofMillis(100)).thenCancel().verify(Duration.ofSeconds(1));
    } finally {
        compositeDisposable.dispose();
    }
    assertThat(sendCount.get()).as("produced").isLessThanOrEqualTo(Queues.SMALL_BUFFER_SIZE);
}

