@Test
public void testPropertyAssignment() {
    EventDrivenConsumer endpoint = (EventDrivenConsumer) context.getBean("completelyDefinedAggregator");
    ReleaseStrategy releaseStrategy = (ReleaseStrategy) context.getBean("releaseStrategy");
    CorrelationStrategy correlationStrategy = (CorrelationStrategy) context.getBean("correlationStrategy");
    Object consumer = new DirectFieldAccessor(endpoint).getPropertyValue("handler");
    assertThat(consumer).isInstanceOf(AggregatingMessageHandler.class);
    DirectFieldAccessor accessor = new DirectFieldAccessor(consumer);
    Object handlerMethods = new DirectFieldAccessor(new DirectFieldAccessor(new DirectFieldAccessor(accessor.getPropertyValue("outputProcessor")).getPropertyValue("processor")).getPropertyValue("delegate")).getPropertyValue("handlerMethods");
    assertThat(handlerMethods).isNotNull();
    Object handlerMethod = new DirectFieldAccessor(new DirectFieldAccessor(new DirectFieldAccessor(accessor.getPropertyValue("outputProcessor")).getPropertyValue("processor")).getPropertyValue("delegate")).getPropertyValue("handlerMethod");
    assertThat(handlerMethod.toString().contains("createSingleMessageFromGroup")).isTrue();
    assertThat(accessor.getPropertyValue("releaseStrategy")).as("The AggregatorEndpoint is not injected with the appropriate ReleaseStrategy instance").isEqualTo(releaseStrategy);
    assertThat(accessor.getPropertyValue("correlationStrategy")).as("The AggregatorEndpoint is not injected with the appropriate CorrelationStrategy instance").isEqualTo(correlationStrategy);
    assertThat(accessor.getPropertyValue("outputChannelName")).as("The AggregatorEndpoint is not injected with the appropriate output channel").isEqualTo("outputChannel");
    assertThat(accessor.getPropertyValue("discardChannelName")).as("The AggregatorEndpoint is not injected with the appropriate discard channel").isEqualTo("discardChannel");
    assertThat(TestUtils.getPropertyValue(consumer, "messagingTemplate.sendTimeout")).as("The AggregatorEndpoint is not set with the appropriate timeout value").isEqualTo(86420000L);
    assertThat(accessor.getPropertyValue("sendPartialResultOnExpiry")).as("The AggregatorEndpoint is not configured with the appropriate 'send partial results on timeout' " + "flag").isEqualTo(true);
    assertThat(TestUtils.getPropertyValue(consumer, "expireGroupsUponTimeout", Boolean.class)).isFalse();
    assertThat(TestUtils.getPropertyValue(consumer, "expireGroupsUponCompletion", Boolean.class)).isTrue();
    assertThat(TestUtils.getPropertyValue(consumer, "minimumTimeoutForEmptyGroups")).isEqualTo(123L);
    assertThat(TestUtils.getPropertyValue(consumer, "groupTimeoutExpression", Expression.class).getExpressionString()).isEqualTo("456");
    assertThat(TestUtils.getPropertyValue(consumer, "lockRegistry")).isSameAs(this.context.getBean(LockRegistry.class));
    assertThat(TestUtils.getPropertyValue(consumer, "taskScheduler")).isSameAs(this.context.getBean("scheduler"));
    assertThat(TestUtils.getPropertyValue(consumer, "messageStore")).isSameAs(this.context.getBean("store"));
    assertThat(TestUtils.getPropertyValue(consumer, "order")).isEqualTo(5);
    assertThat(TestUtils.getPropertyValue(consumer, "forceReleaseAdviceChain")).isNotNull();
    assertThat(TestUtils.getPropertyValue(consumer, "popSequence", Boolean.class)).isFalse();
    assertThat(TestUtils.getPropertyValue(consumer, "expireTimeout")).isEqualTo(250L);
    assertThat(TestUtils.getPropertyValue(consumer, "expireDuration", Duration.class)).isEqualTo(Duration.ofSeconds(10));
}

