@Test
void testPollableReactiveFlow() throws Exception {
    assertThat(this.reactiveTransformer).isInstanceOf(ReactiveStreamsConsumer.class);
    this.reactiveTransformer.setTaskScheduler(new SimpleAsyncTaskScheduler());
    this.inputChannel.send(new GenericMessage<>("1,2,3,4,5"));
    CountDownLatch latch = new CountDownLatch(6);
    Flux.from(this.pollablePublisher).take(6).filter(m -> m.getHeaders().containsKey(IntegrationMessageHeaderAccessor.SEQUENCE_NUMBER)).doOnNext(p -> latch.countDown()).subscribe();
    ExecutorService exec = Executors.newSingleThreadExecutor();
    Future<List<Integer>> future = exec.submit(() -> Flux.just("11,12,13").map(v -> v.split(",")).flatMapIterable(Arrays::asList).map(Integer::parseInt).<Message<Integer>>map(GenericMessage::new).concatWith(this.pollablePublisher).take(7).map(Message::getPayload).collectList().block(Duration.ofSeconds(30)));
    this.inputChannel.send(new GenericMessage<>("6,7,8,9,10"));
    assertThat(latch.await(20, TimeUnit.SECONDS)).isTrue();
    List<Integer> integers = future.get(30, TimeUnit.SECONDS);
    assertThat(integers).isNotNull();
    assertThat(integers.size()).isEqualTo(7);
    exec.shutdownNow();
}

