public void test() {
    assertThat(TestUtils.getPropertyValue(gatewayProxyFactoryBean, "defaultReplyTimeout", Expression.class).getValue()).isEqualTo(123L);
    @SuppressWarnings("unchecked")
    Map<Method, MessagingGatewaySupport> gatewayMap = TestUtils.getPropertyValue(gatewayProxyFactoryBean, "gatewayMap", Map.class);
    int assertions = 0;
    for (Entry<Method, MessagingGatewaySupport> entry : gatewayMap.entrySet()) {
        switch(entry.getKey().getName()) {
            case "annotationShouldNotOverrideDefault" ->
                {
                    assertThat(TestUtils.getPropertyValue(entry.getValue(), "messagingTemplate.receiveTimeout")).isEqualTo(123L);
                    assertions++;
                }
            case "annotationShouldOverrideDefault" ->
                {
                    assertThat(TestUtils.getPropertyValue(entry.getValue(), "messagingTemplate.receiveTimeout")).isEqualTo(234L);
                    assertions++;
                }
            case "annotationShouldOverrideDefaultToInfinity" ->
                {
                    assertThat(TestUtils.getPropertyValue(entry.getValue(), "messagingTemplate.receiveTimeout")).isEqualTo(-1L);
                    assertions++;
                }
            case "explicitTimeoutShouldOverrideDefault" ->
                {
                    assertThat(TestUtils.getPropertyValue(entry.getValue(), "messagingTemplate.receiveTimeout")).isEqualTo(456L);
                    assertions++;
                }
        }
    }
    assertThat(assertions).isEqualTo(4);
}

