@Test
public void testIdempotentReceiverInterceptor() {
    ConcurrentMetadataStore store = new SimpleMetadataStore();
    ExpressionEvaluatingMessageProcessor<String> idempotentKeyStrategy = new ExpressionEvaluatingMessageProcessor<>(new SpelExpressionParser().parseExpression("payload"));
    BeanFactory beanFactory = TEST_INTEGRATION_CONTEXT;
    idempotentKeyStrategy.setBeanFactory(beanFactory);
    IdempotentReceiverInterceptor idempotentReceiverInterceptor = new IdempotentReceiverInterceptor(new MetadataStoreSelector(idempotentKeyStrategy, store));
    idempotentReceiverInterceptor.setThrowExceptionOnRejection(true);
    AtomicReference<Message<?>> handled = new AtomicReference<>();
    MessageHandler idempotentReceiver = handled::set;
    ProxyFactory proxyFactory = new ProxyFactory(idempotentReceiver);
    proxyFactory.addAdvice(idempotentReceiverInterceptor);
    idempotentReceiver = (MessageHandler) proxyFactory.getProxy();
    idempotentReceiver.handleMessage(new GenericMessage<>("foo"));
    assertThat(TestUtils.getPropertyValue(store, "metadata", Map.class).size()).isEqualTo(1);
    assertThat(store.get("foo")).isNotNull();
    try {
        idempotentReceiver.handleMessage(new GenericMessage<>("foo"));
        fail("MessageRejectedException expected");
    } catch (Exception e) {
        assertThat(e).isInstanceOf(MessageRejectedException.class);
    }
    idempotentReceiverInterceptor.setThrowExceptionOnRejection(false);
    idempotentReceiver.handleMessage(new GenericMessage<>("foo"));
    assertThat(handled.get().getHeaders().get(IntegrationMessageHeaderAccessor.DUPLICATE_MESSAGE, Boolean.class)).isTrue();
    assertThat(TestUtils.getPropertyValue(store, "metadata", Map.class).size()).isEqualTo(1);
}

@Test
public void testIdempotentReceiver() {
    Message<String> message = new GenericMessage<>("foo");
    this.input.send(message);
    Message<?> receive = this.output.receive(10000);
    assertThat(receive).isNotNull();
    assertThat(this.fooAdvice.adviceCalled).isEqualTo(1);
    assertThat(TestUtils.getPropertyValue(this.store, "metadata", Map.class).size()).isEqualTo(1);
    assertThat(this.store.get("foo")).isNotNull();
    try {
        this.input.send(message);
        fail("MessageRejectedException expected");
    } catch (Exception e) {
        assertThat(e).isInstanceOf(MessageRejectedException.class);
    }
    this.idempotentReceiverInterceptor.setThrowExceptionOnRejection(false);
    this.input.send(message);
    receive = this.output.receive(10000);
    assertThat(receive).isNotNull();
    assertThat(this.fooAdvice.adviceCalled).isEqualTo(2);
    assertThat(receive.getHeaders().get(IntegrationMessageHeaderAccessor.DUPLICATE_MESSAGE, Boolean.class)).isTrue();
    assertThat(TestUtils.getPropertyValue(this.store, "metadata", Map.class).size()).isEqualTo(1);
    message = new GenericMessage<>("bar");
    for (int i = 0; i < 2; i++) {
        this.input2.send(message);
        receive = this.output.receive(10000);
        assertThat(receive).isNotNull();
    }
    assertThat(receive.getHeaders().get(IntegrationMessageHeaderAccessor.DUPLICATE_MESSAGE, Boolean.class)).isTrue();
    assertThat(TestUtils.getPropertyValue(this.store, "metadata", Map.class).size()).isEqualTo(2);
    assertThat(this.store.get("bar")).isNotNull();
    assertThat(TestUtils.getPropertyValue(this.store2, "metadata", Map.class).size()).isEqualTo(1);
    assertThat(this.store2.get("BAR")).isNotNull();
}

@Test
void verifyLockAroundHandler() throws ExecutionException, InterruptedException, TimeoutException {
    AsyncMessagingTemplate messagingTemplate = new AsyncMessagingTemplate();
    MessagePostProcessor messagePostProcessor = message -> MessageBuilder.fromMessage(message).setHeader(LOCK_KEY_HEADER, "someLock").build();
    Future<Object> test1 = messagingTemplate.asyncConvertSendAndReceive(this.inputChannel, "test1", messagePostProcessor);
    Future<Object> test2 = messagingTemplate.asyncConvertSendAndReceive(this.inputChannel, "test2", messagePostProcessor);
    messagingTemplate.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    assertThat(test1.get(10, TimeUnit.SECONDS)).isEqualTo("test1-1");
    assertThat(test2.get(10, TimeUnit.SECONDS)).isEqualTo("test2-1");
    messagingTemplate.send(this.inputChannel, new GenericMessage<>("no_lock_key"));
    Message<?> receive = this.discardChannel.receive(10_000);
    assertThat(receive).extracting(Message::getPayload).isEqualTo("no_lock_key");
    Future<Object> test3 = messagingTemplate.asyncConvertSendAndReceive(this.inputChannel, "longer_process", messagePostProcessor);
    // Ensure that we have entered a long process before sending new message.
    // Otherwise, there is no guarantee which message would reach the service first.
    assertThat(this.config.longProcessEnteredLatch.await(10, TimeUnit.SECONDS)).isTrue();
    Future<Object> test4 = messagingTemplate.asyncConvertSendAndReceive(this.inputChannel, "test4", messagePostProcessor);
    // It is  hard to achieve exclusive access in time, so expect failure first,
    // then unblock count-down-latch barrier to let success pass.
    assertThat(test4).failsWithin(10, TimeUnit.SECONDS).withThrowableOfType(ExecutionException.class).withRootCauseInstanceOf(TimeoutException.class).withStackTraceContaining("Could not acquire the lock in time: PT1S");
    this.config.longProcessLatch.countDown();
    assertThat(test3.get(10, TimeUnit.SECONDS)).isEqualTo("longer_process-1");
}

