@Test
public void sequence() {
    Message<?> originalMessage = new GenericMessage<>("test");
    this.sequenceRouter.send(originalMessage);
    Message<?> message1 = this.sequenceOut1.receive(1000);
    Message<?> message2 = this.sequenceOut2.receive(1000);
    Message<?> message3 = this.sequenceOut3.receive(1000);
    assertThat(new IntegrationMessageHeaderAccessor(message1).getCorrelationId()).isEqualTo(originalMessage.getHeaders().getId());
    assertThat(new IntegrationMessageHeaderAccessor(message2).getCorrelationId()).isEqualTo(originalMessage.getHeaders().getId());
