    ExecutorService exec = Executors.newSingleThreadExecutor();
    exec.execute(() -> {
        store2.addMessage(testMessage2);
        message2Latch.countDown();
    });
    // Simulate a blocked consumer
    Thread.sleep(10);
    Message<?> t1 = store2.removeMessage(testMessage1.getHeaders().getId());
