    assertThat(message2Latch.await(10, TimeUnit.SECONDS)).isTrue();
    Message<?> t2 = store2.getMessage(testMessage2.getHeaders().getId());
    assertThat(t2).isEqualTo(testMessage2);
    exec.shutdownNow();
}

