@Test
public void controlBusIntegration() {
    try (ConfigurableApplicationContext ctx = new AnnotationConfigApplicationContext(ControlBusEagerConfig.class)) {
        ControlBusCommandRegistry controlBusCommandRegistry = ctx.getBean(IntegrationContextUtils.CONTROL_BUS_COMMAND_REGISTRY_BEAN_NAME, ControlBusCommandRegistry.class);
        Map<String, Map<ControlBusCommandRegistry.CommandMethod, String>> commands = controlBusCommandRegistry.getCommands();
        assertThat(commands).containsKeys("errorChannel", "nullChannel", "taskScheduler", "channel", "_org.springframework.integration.errorLogger", "_org.springframework.integration.errorLogger.handler");
        Map<ControlBusCommandRegistry.CommandMethod, String> commandMethodStringMap = commands.get("channel");
        List<String> controlBusMethodForChannelBean = commandMethodStringMap.keySet().stream().map(ControlBusCommandRegistry.CommandMethod::getMethodName).toList();
        assertThat(controlBusMethodForChannelBean).containsOnly("setLoggingEnabled", "isLoggingEnabled", "setShouldTrack");
        Expression isLoggingEnabledCommand = controlBusCommandRegistry.getExpressionForCommand("nullChannel.isLoggingEnabled");
        StandardEvaluationContext evaluationContext = IntegrationContextUtils.getEvaluationContext(ctx);
        assertThat(isLoggingEnabledCommand.getValue(evaluationContext, boolean.class)).isFalse();
        Expression setLoggingEnabledCommand = controlBusCommandRegistry.getExpressionForCommand("nullChannel.setLoggingEnabled", boolean.class);
        setLoggingEnabledCommand.getValue(evaluationContext, new Object[] { true });
        assertThat(isLoggingEnabledCommand.getValue(evaluationContext, boolean.class)).isTrue();
        ControlBusMessageProcessor controlBusMessageProcessor = ctx.getBean(ControlBusMessageProcessor.class);
        assertThatIllegalArgumentException().isThrownBy(() -> controlBusMessageProcessor.processMessage(new GenericMessage<>("nonSuchBean.command"))).withMessage("There is no registered bean for requested command: nonSuchBean");
        assertThatIllegalArgumentException().isThrownBy(() -> controlBusMessageProcessor.processMessage(new GenericMessage<>("channel.noSuchCommand"))).withMessageStartingWith("No method 'noSuchCommand' found in bean 'bean 'channel'");
        controlBusMessageProcessor.processMessage(MessageBuilder.withPayload("nullChannel.setLoggingEnabled").setHeader(IntegrationMessageHeaderAccessor.CONTROL_BUS_ARGUMENTS, List.of(false)).build());
        assertThat((Boolean) controlBusMessageProcessor.processMessage(new GenericMessage<>("nullChannel.isLoggingEnabled"))).isFalse();
    }
}

