@Test
public void test0() throws Exception {
    ThreadPoolTaskExecutor te = new ThreadPoolTaskExecutor();
    te.setCorePoolSize(1);
    te.setMaxPoolSize(1);
    te.setQueueCapacity(0);
    te.setRejectedExecutionHandler(new CallerBlocksPolicy(10));
    te.initialize();
    AtomicReference<Throwable> e = new AtomicReference<>();
    CountDownLatch latch = new CountDownLatch(1);
    Runnable task = new Runnable() {

        @Override
        public void run() {
            try {
                te.execute(this);
            } catch (TaskRejectedException tre) {
                e.set(tre.getCause());
            }
            latch.countDown();
        }
    };
    try {
        te.execute(task);
        assertThat(latch.await(10, TimeUnit.SECONDS)).isTrue();
        assertThat(e.get()).isInstanceOf(RejectedExecutionException.class).hasMessage("Max wait time expired to queue task");
    } finally {
        te.destroy();
    }
}

@Test
public void test1() throws Exception {
    ThreadPoolTaskExecutor te = new ThreadPoolTaskExecutor();
    te.setCorePoolSize(2);
    te.setMaxPoolSize(2);
    te.setQueueCapacity(1);
    te.setRejectedExecutionHandler(new CallerBlocksPolicy(10000));
    te.initialize();
    AtomicReference<Throwable> e = new AtomicReference<>();
    CountDownLatch latch = new CountDownLatch(3);
    try {
        te.execute(() -> {
            try {
                Runnable foo = () -> {
                    try {
                        Thread.sleep(10);
                    } catch (InterruptedException e1) {
                        Thread.currentThread().interrupt();
                        throw new RuntimeException(e1);
                    } finally {
                        latch.countDown();
                    }
                };
                te.execute(foo);
                // this one will be queued
                te.execute(foo);
                // this one will be blocked and successful later
                te.execute(foo);
            } catch (TaskRejectedException tre) {
                e.set(tre.getCause());
            }
        });
        assertThat(latch.await(10, TimeUnit.SECONDS)).isTrue();
        assertThat(e.get()).isNull();
    } finally {
        te.destroy();
    }
}

@Test
public void testReuseAndStale() {
    final Set<String> strings = new HashSet<>();
    final AtomicBoolean stale = new AtomicBoolean();
    SimplePool<String> pool = stringPool(2, strings, stale);
    String s1 = pool.getItem();
    String s2 = pool.getItem();
    assertThat(s2).isNotSameAs(s1);
    pool.releaseItem(s1);
    String s3 = pool.getItem();
    assertThat(s3).isSameAs(s1);
    stale.set(true);
    pool.releaseItem(s3);
    s3 = pool.getItem();
    assertThat(s3).isNotSameAs(s1);
    assertThat(strings.remove(s1)).isFalse();
    assertThat(pool.getAllocatedCount()).isEqualTo(2);
}

@Test
public void testOverCommitAndResize() {
    final Set<String> strings = new HashSet<>();
    final AtomicBoolean stale = new AtomicBoolean();
    SimplePool<String> pool = stringPool(2, strings, stale);
    String s1 = pool.getItem();
    assertThat(pool.getIdleCount()).isEqualTo(0);
    assertThat(pool.getActiveCount()).isEqualTo(1);
    assertThat(pool.getAllocatedCount()).isEqualTo(1);
    pool.releaseItem(s1);
    assertThat(pool.getIdleCount()).isEqualTo(1);
    assertThat(pool.getActiveCount()).isEqualTo(0);
    assertThat(pool.getAllocatedCount()).isEqualTo(1);
    s1 = pool.getItem();
    assertThat(pool.getIdleCount()).isEqualTo(0);
    assertThat(pool.getActiveCount()).isEqualTo(1);
    assertThat(pool.getAllocatedCount()).isEqualTo(1);
    String s2 = pool.getItem();
    assertThat(s2).isNotSameAs(s1);
    pool.setWaitTimeout(1);
    assertThat(pool.getIdleCount()).isEqualTo(0);
    assertThat(pool.getActiveCount()).isEqualTo(2);
    assertThat(pool.getAllocatedCount()).isEqualTo(2);
    assertThatExceptionOfType(PoolItemNotAvailableException.class).isThrownBy(pool::getItem);
    // resize up
    pool.setPoolSize(4);
    assertThat(pool.getIdleCount()).isEqualTo(0);
    assertThat(pool.getActiveCount()).isEqualTo(2);
    assertThat(pool.getAllocatedCount()).isEqualTo(2);
    String s3 = pool.getItem();
    String s4 = pool.getItem();
    assertThat(pool.getIdleCount()).isEqualTo(0);
    assertThat(pool.getActiveCount()).isEqualTo(4);
    assertThat(pool.getAllocatedCount()).isEqualTo(4);
    pool.releaseItem(s4);
    assertThat(pool.getIdleCount()).isEqualTo(1);
    assertThat(pool.getActiveCount()).isEqualTo(3);
    assertThat(pool.getAllocatedCount()).isEqualTo(4);
    // resize down
    pool.setPoolSize(2);
    assertThat(pool.getIdleCount()).isEqualTo(0);
    assertThat(pool.getActiveCount()).isEqualTo(3);
    assertThat(pool.getPoolSize()).isEqualTo(3);
    assertThat(pool.getAllocatedCount()).isEqualTo(3);
    pool.releaseItem(s3);
    assertThat(pool.getIdleCount()).isEqualTo(0);
    assertThat(pool.getActiveCount()).isEqualTo(2);
    assertThat(pool.getPoolSize()).isEqualTo(2);
    assertThat(pool.getAllocatedCount()).isEqualTo(2);
    assertThat(strings.size()).isEqualTo(2);
    pool.releaseItem(s2);
    pool.releaseItem(s1);
    assertThat(pool.getIdleCount()).isEqualTo(2);
    assertThat(pool.getActiveCount()).isEqualTo(0);
    assertThat(pool.getPoolSize()).isEqualTo(2);
    assertThat(strings.size()).isEqualTo(2);
    assertThat(pool.getAllocatedCount()).isEqualTo(2);
}

