    assertThat(actualFileContent).isEqualTo(expectedFileContent);
    assertThatExceptionOfType(MessageHandlingException.class).isThrownBy(() -> messagingTemplate.sendAndReceive(new GenericMessage<>("String content:"))).withMessageContaining("The destination file already exists at '");
}

