    splitter.handleMessage(receivedStream);
    Message<?> received = out.receive(0);
    assertThat(received.getPayload()).isEqualTo("foo");
    assertThat(received.getHeaders()).containsEntry(FileHeaders.REMOTE_DIRECTORY, "/foo").containsEntry(FileHeaders.REMOTE_FILE, "foo");
