public void testContinuousQueryForOnlyREMOVEDEntryEvent() {
    cqDistributedMap2.put(1, new HazelcastIntegrationTestUser(1, "TestName1", "TestSurname1"));
    cqDistributedMap2.put(2, new HazelcastIntegrationTestUser(2, "TestName2", "TestSurname2"));
    cqDistributedMap2.remove(2);
    Message<?> msg = cqMapChannel2.receive(HazelcastInboundChannelAdapterTestUtils.TIMEOUT);
    assertThat(msg).isNotNull();
    assertThat(msg.getPayload()).isNotNull();
    assertThat(msg.getPayload() instanceof EntryEventMessagePayload).isTrue();
    assertThat(msg.getHeaders().get(HazelcastHeaders.MEMBER)).isNotNull();
    assertThat(msg.getHeaders().get(HazelcastHeaders.EVENT_TYPE)).isEqualTo(EntryEventType.REMOVED.name());
    assertThat(msg.getHeaders().get(HazelcastHeaders.CACHE_NAME)).isEqualTo("cqDistributedMap2");
    assertThat(((EntryEventMessagePayload<Integer, HazelcastIntegrationTestUser>) msg.getPayload()).key()).isEqualTo(Integer.valueOf(2));
    assertThat((((EntryEventMessagePayload<Integer, HazelcastIntegrationTestUser>) msg.getPayload()).oldValue()).getId()).isEqualTo(2);
    assertThat((((EntryEventMessagePayload<Integer, HazelcastIntegrationTestUser>) msg.getPayload()).oldValue()).getName()).isEqualTo("TestName2");
    assertThat((((EntryEventMessagePayload<Integer, HazelcastIntegrationTestUser>) msg.getPayload()).oldValue()).getSurname()).isEqualTo("TestSurname2");
}

