    fccf.registerListener(value -> messageCompletableFuture.complete(value));
    fccf.start();
    fccf.getConnection().send(new GenericMessage<>("test"));
    assertThat(messageCompletableFuture).succeedsWithin(10, TimeUnit.SECONDS).extracting(Message::getPayload).isEqualTo("ok".getBytes());
    assertThat(latch.await(10, TimeUnit.SECONDS)).isTrue();
    assertThatExceptionOfType(UncheckedIOException.class).isThrownBy(() -> fccf.getConnection().send(new GenericMessage<>("test")));
