@Test
public void testWriteTimeout(TestInfo testInfo) throws Exception {
    final CountDownLatch latch = new CountDownLatch(1);
    final CountDownLatch done = new CountDownLatch(1);
    final AtomicReference<ServerSocket> serverSocket = new AtomicReference<>();
    this.executor.execute(() -> {
        try {
            ServerSocket server = ServerSocketFactory.getDefault().createServerSocket(0);
            logger.debug(testInfo.getTestMethod().get().getName() + " starting server for " + server.getLocalPort());
            serverSocket.set(server);
            latch.countDown();
            Socket s = server.accept();
            // block so we fill the buffer
            done.await(10, TimeUnit.SECONDS);
            s.close();
        } catch (Exception e) {
            ReflectionUtils.rethrowRuntimeException(e);
        }
    });
    assertThat(latch.await(30, TimeUnit.SECONDS)).isTrue();
    TcpNioClientConnectionFactory factory = new TcpNioClientConnectionFactory("localhost", serverSocket.get().getLocalPort());
    factory.setLookupHost(true);
    AtomicReference<String> connectionId = new AtomicReference<>();
    factory.setApplicationEventPublisher(event -> {
        if (event instanceof TcpConnectionOpenEvent) {
            connectionId.set(((TcpConnectionOpenEvent) event).getConnectionId());
        }
    });
    factory.setSoTimeout(100);
    factory.start();
    try {
        TcpConnection connection = factory.getConnection();
        connection.send(MessageBuilder.withPayload(new byte[1000000]).build());
    } catch (MessagingException e) {
        assertThat(e.getCause() instanceof SocketTimeoutException).as("Expected SocketTimeoutException, got " + e.getClass().getSimpleName() + ":" + e.getMessage()).isTrue();
    }
    done.countDown();
    factory.stop();
    serverSocket.get().close();
    assertThat(connectionId.get()).startsWith("localhost");
}

