@Test
void testAsyncTimeout() throws Exception {
    final CountDownLatch latch = new CountDownLatch(1);
    final CountDownLatch doneLatch = new CountDownLatch(1);
    final AtomicBoolean done = new AtomicBoolean();
    final AtomicReference<ServerSocket> serverSocket = new AtomicReference<>();
    AbstractClientConnectionFactory ccf = null;
    ThreadPoolTaskScheduler sched = new ThreadPoolTaskScheduler();
    sched.initialize();
    try {
        this.executor.execute(() -> {
            try {
                ServerSocket server = ServerSocketFactory.getDefault().createServerSocket(0, 100);
                serverSocket.set(server);
                latch.countDown();
                int i = 0;
                while (true) {
                    Socket socket = server.accept();
                    doneLatch.await(10, TimeUnit.SECONDS);
                    socket.close();
                }
            } catch (Exception e) {
                if (!done.get()) {
                    e.printStackTrace();
                }
            }
        });
        assertThat(latch.await(10000, TimeUnit.MILLISECONDS)).isTrue();
        ccf = new TcpNetClientConnectionFactory("localhost", serverSocket.get().getLocalPort());
        ccf.setSoTimeout(10000);
        ccf.start();
        TcpOutboundGateway gateway = new TcpOutboundGateway();
        gateway.setConnectionFactory(ccf);
        gateway.setAsync(true);
        gateway.setRemoteTimeout(10);
        QueueChannel replyChannel = new QueueChannel();
        gateway.setRequiresReply(true);
        gateway.setOutputChannel(replyChannel);
        gateway.setBeanFactory(mock(BeanFactory.class));
        gateway.setTaskScheduler(sched);
        gateway.afterPropertiesSet();
        QueueChannel errorChannel = new QueueChannel();
        gateway.handleMessage(MessageBuilder.withPayload("Test1").setErrorChannel(errorChannel).build());
        Message<?> reply = errorChannel.receive(10000);
        assertThat(reply).isInstanceOf(ErrorMessage.class);
        assertThat(reply.getPayload()).isInstanceOf(MessageTimeoutException.class);
        doneLatch.countDown();
        gateway.stop();
    } finally {
        done.set(true);
        if (ccf != null) {
            ccf.stop();
        }
        if (serverSocket.get() != null) {
            serverSocket.get().close();
        }
        sched.shutdown();
    }
}

@Test
void semaphoreIsReleasedOnAsyncSendFailure() throws InterruptedException {
    AbstractClientConnectionFactory ccf = mock(AbstractClientConnectionFactory.class);
    TcpConnection connection = mock(TcpConnectionSupport.class);
    given(connection.getConnectionId()).willReturn("testId");
    willThrow(new RuntimeException("intentional")).given(connection).send(any(Message.class));
    willReturn(connection).given(ccf).getConnection();
    TcpOutboundGateway gateway = new TcpOutboundGateway();
    gateway.setConnectionFactory(ccf);
    gateway.setAsync(true);
    gateway.setBeanFactory(mock(BeanFactory.class));
    gateway.setRemoteTimeout(-1);
    gateway.afterPropertiesSet();
    assertThatExceptionOfType(MessageHandlingException.class).isThrownBy(() -> gateway.handleMessage(new GenericMessage<>("Test1"))).withCauseExactlyInstanceOf(RuntimeException.class).withStackTraceContaining("intentional");
    assertThatExceptionOfType(MessageHandlingException.class).isThrownBy(() -> gateway.handleMessage(new GenericMessage<>("Test2"))).withCauseExactlyInstanceOf(RuntimeException.class).withStackTraceContaining("intentional");
}

