public void testNioSingleUseWithInboundMany() throws Exception {
    final AtomicReference<ServerSocket> serverSocket = new AtomicReference<>();
    final CountDownLatch latch = new CountDownLatch(1);
    final Semaphore semaphore = new Semaphore(0);
    final AtomicBoolean done = new AtomicBoolean();
    final List<Socket> serverSockets = new ArrayList<>();
    this.executor.execute(() -> {
        try {
            ServerSocket server = ServerSocketFactory.getDefault().createServerSocket(0, 100);
            serverSocket.set(server);
            latch.countDown();
            for (int i = 0; i < 100; i++) {
                final Socket socket = server.accept();
                serverSockets.add(socket);
                final int j = i;
                this.executor.execute(() -> {
                    semaphore.release();
                    byte[] b = new byte[9];
                    try {
                        readFully(socket.getInputStream(), b);
                        b = ("Reply" + j + "\r\n").getBytes();
                        socket.getOutputStream().write(b);
                    } catch (IOException e1) {
                        e1.printStackTrace();
                    } finally {
                        try {
                            socket.close();
                        } catch (IOException e2) {
                        }
                    }
                });
            }
            server.close();
        } catch (Exception e) {
            if (!done.get()) {
                e.printStackTrace();
            }
        }
    });
    assertThat(latch.await(10, TimeUnit.SECONDS)).isTrue();
    AbstractConnectionFactory ccf = new TcpNioClientConnectionFactory("localhost", serverSocket.get().getLocalPort());
    noopPublisher(ccf);
    ByteArrayCrLfSerializer serializer = new ByteArrayCrLfSerializer();
    ccf.setSerializer(serializer);
    ccf.setDeserializer(serializer);
    ccf.setSoTimeout(10000);
    ccf.setSingleUse(true);
    ccf.setTaskExecutor(this.executor);
    ccf.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    ccf.afterPropertiesSet();
    ccf.start();
    TcpSendingMessageHandler handler = new TcpSendingMessageHandler();
    handler.setConnectionFactory(ccf);
    TcpReceivingChannelAdapter adapter = new TcpReceivingChannelAdapter();
    adapter.setConnectionFactory(ccf);
    QueueChannel channel = new QueueChannel();
    adapter.setOutputChannel(channel);
    int i = 0;
    try {
        for (i = 100; i < 200; i++) {
            handler.handleMessage(MessageBuilder.withPayload("Test" + i).build());
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail("Exception at " + i);
    }
    assertThat(semaphore.tryAcquire(100, 20000, TimeUnit.MILLISECONDS)).isTrue();
    Set<String> replies = new HashSet<>();
    for (i = 100; i < 200; i++) {
        Message<?> mOut = channel.receive(20000);
        assertThat(mOut).isNotNull();
        replies.add(new String((byte[]) mOut.getPayload()));
    }
    for (i = 0; i < 100; i++) {
        assertThat(replies.remove("Reply" + i)).as("Reply" + i + " missing").isTrue();
    }
    done.set(true);
    ccf.stop();
    serverSocket.get().close();
}

