@Test
public void testTruncation() {
    String test = "ABCD";
    Message<byte[]> message = MessageBuilder.withPayload(test.getBytes()).build();
    DatagramPacketMessageMapper mapper = new DatagramPacketMessageMapper();
    mapper.setAckAddress("localhost:11111");
    mapper.setAcknowledge(false);
    mapper.setLengthCheck(true);
    DatagramPacket packet = mapper.fromMessage(message);
    // Force a truncation failure
    ByteBuffer bb = ByteBuffer.wrap(packet.getData());
    int bigLen = 99999;
    bb.putInt(bigLen);
    packet.setSocketAddress(new InetSocketAddress("localhost", 22222));
    assertThatExceptionOfType(MessageMappingException.class).isThrownBy(() -> mapper.toMessage(packet)).withMessageContaining("expected " + (bigLen + 4) + ", received " + (test.length() + 4));
}

@Test
public void verifySendMulticast(MulticastCondition multicastCondition) throws Exception {
    MulticastSocket socket;
    try {
        socket = new MulticastSocket();
    } catch (Exception e) {
        return;
    }
    final int testPort = socket.getLocalPort();
    final String multicastAddress = multicastCondition.getGroup();
    final String payload = "foo";
    final CountDownLatch listening = new CountDownLatch(2);
    final CountDownLatch received = new CountDownLatch(2);
    Runnable catcher = () -> {
        try {
            byte[] buffer = new byte[8];
            DatagramPacket receivedPacket = new DatagramPacket(buffer, buffer.length);
            MulticastSocket socket1 = new MulticastSocket(testPort);
            socket1.setNetworkInterface(multicastCondition.getNic());
            InetAddress group = InetAddress.getByName(multicastAddress);
            socket1.joinGroup(new InetSocketAddress(group, 0), null);
            listening.countDown();
            socket1.receive(receivedPacket);
            socket1.close();
            byte[] src = receivedPacket.getData();
            int length = receivedPacket.getLength();
            int offset = receivedPacket.getOffset();
            byte[] dest = new byte[length];
            System.arraycopy(src, offset, dest, 0, length);
            assertThat(new String(dest)).isEqualTo(payload);
            received.countDown();
        } catch (Exception e) {
            listening.countDown();
            e.printStackTrace();
        }
    };
    Executor executor = new SimpleAsyncTaskExecutor("verifySendMulticast-");
    executor.execute(catcher);
    executor.execute(catcher);
    assertThat(listening.await(10000, TimeUnit.MILLISECONDS)).isTrue();
    MulticastSendingMessageHandler handler = new MulticastSendingMessageHandler(multicastAddress, testPort);
    handler.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    NetworkInterface nic = multicastCondition.getNic();
    if (nic != null) {
        String hostName = null;
        Enumeration<InetAddress> addressesFromNetworkInterface = nic.getInetAddresses();
        while (addressesFromNetworkInterface.hasMoreElements()) {
            InetAddress inetAddress = addressesFromNetworkInterface.nextElement();
            if (inetAddress.isSiteLocalAddress() && !inetAddress.isAnyLocalAddress() && !inetAddress.isLinkLocalAddress() && !inetAddress.isLoopbackAddress()) {
                hostName = inetAddress.getHostName();
                break;
            }
        }
        handler.setLocalAddress(hostName);
    }
    handler.afterPropertiesSet();
    handler.handleMessage(MessageBuilder.withPayload(payload).build());
    assertThat(received.await(10000, TimeUnit.MILLISECONDS)).isTrue();
    handler.stop();
    socket.close();
}

@Test
public void verifySendMulticastWithAcks(MulticastCondition multicastCondition) throws Exception {
    MulticastSocket socket;
    try {
        socket = new MulticastSocket();
    } catch (Exception e) {
        return;
    }
    final int testPort = socket.getLocalPort();
    final AtomicInteger ackPort = new AtomicInteger();
    final String multicastAddress = multicastCondition.getGroup();
    final String payload = "foobar";
    final CountDownLatch listening = new CountDownLatch(2);
    final CountDownLatch ackListening = new CountDownLatch(1);
    final CountDownLatch ackSent = new CountDownLatch(2);
    NetworkInterface nic = multicastCondition.getNic();
    Runnable catcher = () -> {
        try {
            byte[] buffer = new byte[1000];
            DatagramPacket receivedPacket = new DatagramPacket(buffer, buffer.length);
            MulticastSocket socket1 = new MulticastSocket(testPort);
            socket1.setNetworkInterface(multicastCondition.getNic());
            socket1.setSoTimeout(8000);
            InetAddress group = InetAddress.getByName(multicastAddress);
            socket1.joinGroup(new InetSocketAddress(group, 0), null);
            listening.countDown();
            assertThat(ackListening.await(10, TimeUnit.SECONDS)).isTrue();
            socket1.receive(receivedPacket);
            socket1.close();
            byte[] src = receivedPacket.getData();
            int length = receivedPacket.getLength();
            int offset = receivedPacket.getOffset();
            byte[] dest = new byte[6];
            System.arraycopy(src, offset + length - 6, dest, 0, 6);
            assertThat(new String(dest)).isEqualTo(payload);
            DatagramPacketMessageMapper mapper = new DatagramPacketMessageMapper();
            mapper.setAcknowledge(true);
            mapper.setLengthCheck(true);
            mapper.setBeanFactory(TEST_INTEGRATION_CONTEXT);
            Message<byte[]> message = mapper.toMessage(receivedPacket);
            Object id = message.getHeaders().get(IpHeaders.ACK_ID);
            byte[] ack = id.toString().getBytes();
            InetAddress inetAddress = null;
            Enumeration<InetAddress> addressesFromNetworkInterface = nic.getInetAddresses();
            while (addressesFromNetworkInterface.hasMoreElements()) {
                InetAddress address = addressesFromNetworkInterface.nextElement();
                if (address.isSiteLocalAddress() && !address.isAnyLocalAddress() && !address.isLinkLocalAddress() && !address.isLoopbackAddress()) {
                    inetAddress = address;
                    break;
                }
            }
            DatagramPacket ackPack = new DatagramPacket(ack, ack.length, new InetSocketAddress(inetAddress, ackPort.get()));
            DatagramSocket out = new DatagramSocket();
            out.send(ackPack);
            out.close();
            ackSent.countDown();
            socket1.close();
        } catch (Exception e) {
            listening.countDown();
            e.printStackTrace();
        }
    };
    Executor executor = new SimpleAsyncTaskExecutor("verifySendMulticastWithAcks-");
    executor.execute(catcher);
    executor.execute(catcher);
    assertThat(listening.await(10000, TimeUnit.MILLISECONDS)).isTrue();
    MulticastSendingMessageHandler handler = new MulticastSendingMessageHandler(multicastAddress, testPort, true, true, "localhost", 0, 10000);
    if (nic != null) {
        String hostName = null;
        Enumeration<InetAddress> addressesFromNetworkInterface = nic.getInetAddresses();
        while (addressesFromNetworkInterface.hasMoreElements()) {
            InetAddress inetAddress = addressesFromNetworkInterface.nextElement();
            if (inetAddress.isSiteLocalAddress() && !inetAddress.isAnyLocalAddress() && !inetAddress.isLinkLocalAddress() && !inetAddress.isLoopbackAddress()) {
                hostName = inetAddress.getHostName();
                break;
            }
        }
        handler.setLocalAddress(hostName);
    }
    handler.setMinAcksForSuccess(2);
    handler.setBeanFactory(TEST_INTEGRATION_CONTEXT);
    handler.afterPropertiesSet();
    handler.start();
    waitAckListening(handler);
    ackPort.set(handler.getAckPort());
    ackListening.countDown();
    handler.handleMessage(MessageBuilder.withPayload(payload).build());
    assertThat(ackSent.await(10000, TimeUnit.MILLISECONDS)).isTrue();
    handler.stop();
    socket.close();
}

