@Test
void testSecondThreadLoses() throws Exception {
    for (int i = 0; i < 100; i++) {
        final JdbcLockRegistry registry1 = this.registry;
        final JdbcLockRegistry registry2 = this.child.getBean(JdbcLockRegistry.class);
        final Lock lock1 = registry1.obtain("foo");
        final AtomicBoolean locked = new AtomicBoolean();
        final CountDownLatch latch1 = new CountDownLatch(1);
        final CountDownLatch latch2 = new CountDownLatch(1);
        final CountDownLatch latch3 = new CountDownLatch(1);
        lock1.lockInterruptibly();
        new SimpleAsyncTaskExecutor().execute(() -> {
            Lock lock2 = registry2.obtain("foo");
            try {
                latch1.countDown();
                lock2.lockInterruptibly();
                latch2.await(10, TimeUnit.SECONDS);
                locked.set(true);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            } finally {
                lock2.unlock();
                latch3.countDown();
            }
        });
        assertThat(latch1.await(10, TimeUnit.SECONDS)).isTrue();
        assertThat(locked.get()).isFalse();
        lock1.unlock();
        latch2.countDown();
        assertThat(latch3.await(10, TimeUnit.SECONDS)).isTrue();
        assertThat(locked.get()).isTrue();
    }
}

@Test
void testBothLock() throws Exception {
    for (int i = 0; i < 100; i++) {
        final JdbcLockRegistry registry1 = this.registry;
        final JdbcLockRegistry registry2 = this.child.getBean(JdbcLockRegistry.class);
        final List<String> locked = new ArrayList<>();
        final CountDownLatch latch = new CountDownLatch(2);
        ExecutorService pool = Executors.newFixedThreadPool(2);
        pool.execute(() -> {
            Lock lock = registry1.obtain("foo");
            try {
                lock.lockInterruptibly();
                locked.add("1");
                latch.countDown();
            } catch (InterruptedException e1) {
                Thread.currentThread().interrupt();
            } finally {
                try {
                    lock.unlock();
                } catch (Exception e2) {
                    // ignore
                }
            }
        });
        pool.execute(() -> {
            Lock lock = registry2.obtain("foo");
            try {
                lock.lockInterruptibly();
                locked.add("2");
                latch.countDown();
            } catch (InterruptedException e1) {
                Thread.currentThread().interrupt();
            } finally {
                try {
                    lock.unlock();
                } catch (Exception e2) {
                    // ignore
                }
            }
        });
        assertThat(latch.await(10, TimeUnit.SECONDS)).isTrue();
        // eventually they both get the lock and release it
        assertThat(locked.contains("1")).isTrue();
        assertThat(locked.contains("2")).isTrue();
        pool.shutdownNow();
    }
}

@Test
void testOnlyOneLock() throws Exception {
    for (int i = 0; i < 100; i++) {
        final BlockingQueue<String> locked = new LinkedBlockingQueue<>();
        final CountDownLatch latch = new CountDownLatch(20);
        ExecutorService pool = Executors.newFixedThreadPool(20);
        ArrayList<Callable<Boolean>> tasks = new ArrayList<>();
        for (int j = 0; j < 20; j++) {
            Callable<Boolean> task = () -> {
                DefaultLockRepository client = new DefaultLockRepository(this.dataSource);
                client.setApplicationContext(this.context);
                client.afterPropertiesSet();
                client.afterSingletonsInstantiated();
                Lock lock = new JdbcLockRegistry(client).obtain("foo");
                try {
                    if (locked.isEmpty() && lock.tryLock(Long.MAX_VALUE, TimeUnit.MILLISECONDS)) {
                        if (locked.isEmpty()) {
                            locked.add("done");
                            return true;
                        }
                    }
                } finally {
                    try {
                        lock.unlock();
                    } catch (Exception e) {
                        // ignore
                    }
                    latch.countDown();
                }
                return false;
            };
            tasks.add(task);
        }
        LOGGER.info("Starting: " + i);
        pool.invokeAll(tasks);
        assertThat(latch.await(10, TimeUnit.SECONDS)).isTrue();
        assertThat(locked.size()).isEqualTo(1);
        assertThat(locked.contains("done")).isTrue();
        pool.shutdownNow();
    }
}

@Test
void testExclusiveAccess() throws Exception {
    DefaultLockRepository client1 = new DefaultLockRepository(dataSource);
    client1.setApplicationContext(this.context);
    client1.afterPropertiesSet();
    client1.afterSingletonsInstantiated();
    DefaultLockRepository client2 = new DefaultLockRepository(dataSource);
    client2.setApplicationContext(this.context);
    client2.afterPropertiesSet();
    client2.afterSingletonsInstantiated();
    Lock lock1 = new JdbcLockRegistry(client1).obtain("foo");
    final BlockingQueue<Integer> data = new LinkedBlockingQueue<>();
    final CountDownLatch latch1 = new CountDownLatch(1);
    lock1.lockInterruptibly();
    new SimpleAsyncTaskExecutor().execute(() -> {
        Lock lock2 = new JdbcLockRegistry(client2).obtain("foo");
        try {
            latch1.countDown();
            StopWatch stopWatch = new StopWatch();
            stopWatch.start();
            lock2.lockInterruptibly();
            stopWatch.stop();
            data.add(4);
            Thread.sleep(10);
            data.add(5);
            Thread.sleep(10);
            data.add(6);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            lock2.unlock();
        }
    });
    assertThat(latch1.await(10, TimeUnit.SECONDS)).isTrue();
    data.add(1);
    Thread.sleep(100);
    data.add(2);
    Thread.sleep(100);
    data.add(3);
    lock1.unlock();
    for (int i = 0; i < 6; i++) {
        Integer integer = data.poll(10, TimeUnit.SECONDS);
        assertThat(integer).isNotNull();
        assertThat(integer.intValue()).isEqualTo(i + 1);
    }
}

