        Lock obtainLock0 = registry.obtain("foo:" + i);
        obtainLock0.lock();
        obtainLock0.unlock();
    }
    for (int i = dummyLockCnt; i < threadCnt + dummyLockCnt; i++) {
        int finalI = i;
        executorService.submit(() -> {
