/**
 * Validates that JOG will recreate a temporary queue
 * once a failure detected and that the messages will still be properly correlated
 */
@Test
public void brokenBrokerTest() throws Exception {
    Configuration configuration = new ConfigurationImpl().addAcceptorConfiguration("jms", "tcp://localhost:61623").setPersistenceEnabled(false).setSecurityEnabled(false).setJMXManagementEnabled(false).setJournalDatasync(false);
    EmbeddedActiveMQ broker = new EmbeddedActiveMQ().setConfiguration(configuration).start();
    ClassPathXmlApplicationContext context = new ClassPathXmlApplicationContext("broken-broker.xml", this.getClass());
    final RequestReplyExchanger gateway = context.getBean(RequestReplyExchanger.class);
    int replyCounter = 0;
    int timeoutCounter = 0;
    for (int i = 0; i < 50; i++) {
        try {
            assertThat(gateway.exchange(new GenericMessage<>(String.valueOf(i))).getPayload()).isEqualTo(i + "");
            replyCounter++;
        } catch (Exception e) {
            timeoutCounter++;
        }
        if (i == 0 || i == 20 || i == 40) {
            Object replyDestination = TestUtils.getPropertyValue(context.getBean("jog"), "handler.replyDestination");
            if (replyDestination != null) {
                broker.getActiveMQServer().destroyQueue(((ActiveMQDestination) replyDestination).getSimpleAddress());
            }
        }
    }
    assertThat(replyCounter + timeoutCounter).isEqualTo(50);
    context.close();
    broker.stop();
}

@Test
public void testConcurrently() throws Exception {
    ExecutorService executor = Executors.newFixedThreadPool(10);
    try (ClassPathXmlApplicationContext context = new ClassPathXmlApplicationContext("multi-producer-and-consumers-temp-reply.xml", this.getClass())) {
        final RequestReplyExchanger gateway = context.getBean(RequestReplyExchanger.class);
        final int testNumbers = 30;
        final CountDownLatch latch = new CountDownLatch(testNumbers);
        final AtomicInteger failures = new AtomicInteger();
        final AtomicInteger timeouts = new AtomicInteger();
        final AtomicInteger mismatches = new AtomicInteger();
        for (int i = 0; i < testNumbers; i++) {
            final int y = i;
            executor.execute(() -> {
                try {
                    String reply = (String) gateway.exchange(new GenericMessage<>(String.valueOf(y))).getPayload();
                    if (!String.valueOf(y).equals(reply)) {
                        mismatches.incrementAndGet();
                    }
                } catch (Exception e) {
                    if (e instanceof MessageDeliveryException) {
                        timeouts.incrementAndGet();
                    } else {
                        logger.error("testConcurrently failure", e);
                        failures.incrementAndGet();
                    }
                }
                latch.countDown();
            });
        }
        assertThat(latch.await(30, TimeUnit.SECONDS)).isTrue();
        print(failures, timeouts, mismatches, testNumbers);
        assertThat(mismatches.get()).isEqualTo(0);
        assertThat(failures.get()).isEqualTo(0);
        assertThat(timeouts.get()).isEqualTo(0);
    } finally {
        executor.shutdownNow();
    }
}

