@Test
public void byteArrayMessage() throws Exception {
    byte[] payload = { 1, 2, 3 };
    org.springframework.messaging.Message<?> message = MessageBuilder.withPayload(payload).setHeader(MailHeaders.ATTACHMENT_FILENAME, "attachment.txt").setHeader(MailHeaders.TO, MailTestsHelper.TO).build();
    this.handler.handleMessage(message);
    assertThat(this.mailSender.getSentMimeMessages().size()).as("only one mime message should have been sent").isEqualTo(1);
    assertThat(this.mailSender.getSentSimpleMailMessages().size()).as("no simple message must be sent").isEqualTo(0);
