@Test
void testChangeStreamMessageProducer() {
    Person person1 = new Person("John", 38);
    Person person2 = new Person("Josh", 39);
    Person person3 = new Person("Jack", 37);
    this.changeStreamMessageProducer.start();
    StepVerifier stepVerifier = Flux.from(this.fluxMessageChannel).as(StepVerifier::create).assertNext((message) -> {
        assertThat(message.getPayload()).isInstanceOf(ChangeStreamEvent.class).extracting("body").asInstanceOf(InstanceOfAssertFactories.type(Person.class)).isEqualTo(person1);
        assertThat(message.getHeaders()).containsEntry(MongoHeaders.COLLECTION_NAME, "person").containsEntry(MongoHeaders.CHANGE_STREAM_OPERATION_TYPE, OperationType.INSERT).containsKeys(MongoHeaders.CHANGE_STREAM_TIMESTAMP, MongoHeaders.CHANGE_STREAM_RESUME_TOKEN);
    }).assertNext((message) -> assertThat(message.getPayload()).extracting("body").isEqualTo(person2)).assertNext((message) -> assertThat(message.getPayload()).extracting("body").isEqualTo(person3)).thenCancel().verifyLater();
    Flux.concat(this.mongoTemplate.insert(person1), this.mongoTemplate.insert(person2), this.mongoTemplate.insert(person3)).as(StepVerifier::create).expectNextCount(3).verifyComplete();
    stepVerifier.verify(Duration.ofSeconds(10));
    this.changeStreamMessageProducer.stop();
}

