@Test
public void referencedScript() throws Exception {
    QueueChannel replyChannel = new QueueChannel();
    replyChannel.setBeanName("returnAddress");
    for (int i = 1; i <= 3; i++) {
        Message<?> message = MessageBuilder.withPayload("test-" + i).setReplyChannel(replyChannel).build();
        this.referencedScriptInput.send(message);
        Thread.sleep(1000);
    }
    String value1 = (String) replyChannel.receive(0).getPayload();
    String value2 = (String) replyChannel.receive(0).getPayload();
    String value3 = (String) replyChannel.receive(0).getPayload();
    assertThat(value1.startsWith("python-test-1-foo (foo2) - bar")).isTrue();
    assertThat(value2.startsWith("python-test-2-foo (foo2) - bar")).isTrue();
    assertThat(value3.startsWith("python-test-3-foo (foo2) - bar")).isTrue();
    // because we are using 'prototype bean the suffix date will be
    // different
    assertThat(value1.substring(value1.indexOf(":") + 1, value1.lastIndexOf(":")).equals(value2.substring(value1.indexOf(":") + 1, value1.lastIndexOf(":")))).isFalse();
    assertThat(value1.substring(value1.indexOf(":") + 1, value1.lastIndexOf(":")).equals(value1.substring(value1.lastIndexOf(":")))).isFalse();
    assertThat(value2.substring(value1.indexOf(":") + 1, value1.lastIndexOf(":")).equals(value3.substring(value1.indexOf(":") + 1, value1.lastIndexOf(":")))).isFalse();
    assertThat(value1.substring(value1.lastIndexOf(":") + 1).equals(value2.substring(value1.lastIndexOf(":") + 1))).isFalse();
    assertThat(value2.substring(value1.lastIndexOf(":") + 1).equals(value3.substring(value1.lastIndexOf(":") + 1))).isFalse();
    assertThat(replyChannel.receive(0)).isNull();
}

