@Test
public void testWithLocalFiles() {
    ConfigurableApplicationContext context = new ClassPathXmlApplicationContext("InboundChannelAdapterParserTests-context.xml", this.getClass());
    assertThat(new File("src/main/resources").exists()).isTrue();
    Object adapter = context.getBean("sftpAdapterAutoCreate");
    assertThat(adapter instanceof SourcePollingChannelAdapter).isTrue();
    SftpInboundFileSynchronizingMessageSource source = (SftpInboundFileSynchronizingMessageSource) TestUtils.getPropertyValue(adapter, "source");
    assertThat(source).isNotNull();
    PriorityBlockingQueue<?> blockingQueue = TestUtils.getPropertyValue(adapter, "source.fileSource.toBeReceived", PriorityBlockingQueue.class);
    Comparator<?> comparator = blockingQueue.comparator();
    assertThat(comparator).isNotNull();
    SftpInboundFileSynchronizer synchronizer = TestUtils.getPropertyValue(source, "synchronizer", SftpInboundFileSynchronizer.class);
    assertThat(TestUtils.getPropertyValue(synchronizer, "remoteDirectoryExpression", Expression.class).getExpressionString()).isEqualTo("'/foo'");
    assertThat(TestUtils.getPropertyValue(synchronizer, "localFilenameGeneratorExpression")).isNotNull();
    assertThat(TestUtils.getPropertyValue(synchronizer, "preserveTimestamp", Boolean.class)).isTrue();
    String remoteFileSeparator = (String) TestUtils.getPropertyValue(synchronizer, "remoteFileSeparator");
    assertThat(TestUtils.getPropertyValue(synchronizer, "temporaryFileSuffix", String.class)).isEqualTo(".bar");
    assertThat(TestUtils.getPropertyValue(synchronizer, "remoteFileMetadataStore")).isSameAs(context.getBean(MetadataStore.class));
    assertThat(TestUtils.getPropertyValue(synchronizer, "metadataStorePrefix", String.class)).isEqualTo("testPrefix");
    assertThat(remoteFileSeparator).isNotNull();
    assertThat(remoteFileSeparator).isEqualTo(".");
    PollableChannel requestChannel = context.getBean("requestChannel", PollableChannel.class);
    ((Lifecycle) adapter).start();
    assertThat(requestChannel.receive(10000)).isNotNull();
    FileListFilter<?> acceptAllFilter = context.getBean("acceptAllFilter", FileListFilter.class);
    @SuppressWarnings("unchecked")
    Collection<FileListFilter<?>> filters = TestUtils.getPropertyValue(source, "fileSource.scanner.filter.fileFilters", Collection.class);
    assertThat(filters).contains(acceptAllFilter);
    assertThat(source.getMaxFetchSize()).isEqualTo(42);
    context.close();
}

