@Test
public void testAge() {
    SftpLastModifiedFileListFilter filter = new SftpLastModifiedFileListFilter();
    SftpClient.Attributes attributes1 = new SftpClient.Attributes();
    attributes1.setModifyTime(FileTime.from(Instant.now()));
    SftpClient.Attributes attributes2 = new SftpClient.Attributes();
    attributes2.setModifyTime(FileTime.from(Instant.now()));
    SftpClient.DirEntry sftpFile1 = new SftpClient.DirEntry("foo", "foo", attributes1);
    SftpClient.DirEntry sftpFile2 = new SftpClient.DirEntry("bar", "bar", attributes2);
    SftpClient.DirEntry[] files = new SftpClient.DirEntry[] { sftpFile1, sftpFile2 };
    assertThat(filter.filterFiles(files)).hasSize(0);
    assertThat(filter.accept(sftpFile2)).isFalse();
    FileTime fileTime = FileTime.from(Instant.now().minus(Duration.ofDays(1)));
    sftpFile2.getAttributes().setModifyTime(fileTime);
    assertThat(filter.filterFiles(files)).hasSize(1);
    assertThat(filter.accept(sftpFile2)).isTrue();
}

@Test
public void testRollback() throws Exception {
    SftpPersistentAcceptOnceFileListFilter filter = new SftpPersistentAcceptOnceFileListFilter(new SimpleMetadataStore(), "rollback:");
    SftpClient.Attributes attrs = new SftpClient.Attributes();
    attrs.setModifyTime(FileTime.from(Instant.now()));
    SftpClient.DirEntry sftpFile1 = new SftpClient.DirEntry("file1", null, attrs);
    SftpClient.DirEntry sftpFile2 = new SftpClient.DirEntry("file2", null, attrs);
    SftpClient.DirEntry sftpFile3 = new SftpClient.DirEntry("file3", null, attrs);
    SftpClient.DirEntry[] files = new SftpClient.DirEntry[] { sftpFile1, sftpFile2, sftpFile3 };
    List<SftpClient.DirEntry> passed = filter.filterFiles(files);
    assertThat(passed.toArray()).isEqualTo(files);
    List<SftpClient.DirEntry> now = filter.filterFiles(files);
    assertThat(now).isEmpty();
    filter.rollback(passed.get(1), passed);
    now = filter.filterFiles(files);
    assertThat(now).hasSize(2).extracting(SftpClient.DirEntry::getFilename).contains("file2", "file3");
    now = filter.filterFiles(files);
    assertThat(now).isEmpty();
    filter.close();
}

