/*
	 * Verify the socket is closed if the channel.connect() fails.
	 * INT-3305
	 */
@Test
void testConnectFailSocketOpen() throws Exception {
    try (SshServer server = SshServer.setUpDefaultServer()) {
        server.setPasswordAuthenticator((arg0, arg1, arg2) -> true);
        server.setPort(0);
        server.setKeyPairProvider(new SimpleGeneratorHostKeyProvider(new File("hostkey.ser").toPath()));
        server.start();
        DefaultSftpSessionFactory f = new DefaultSftpSessionFactory();
        f.setHost("localhost");
        f.setPort(server.getPort());
        f.setUser("user");
        f.setPassword("pass");
        int n = 0;
        while (true) {
            try {
                f.getSession().connect();
                fail("Expected Exception");
            } catch (Exception e) {
                if (e instanceof IllegalStateException && "failed to create SFTP Session".equals(e.getMessage())) {
                    if (e.getCause() instanceof IllegalStateException) {
                        if (e.getCause().getCause() instanceof ConnectException) {
                            assertThat(n++ < 100).as("Server failed to start in 10 seconds").isTrue();
                            Thread.sleep(100);
                            continue;
                        }
                    }
                }
                assertThat(e).isInstanceOf(IllegalStateException.class);
                assertThat(e.getCause()).isInstanceOf(SshException.class);
                assertThat(e.getCause().getMessage()).isEqualTo("Server key did not validate");
                break;
            }
        }
        n = 0;
        while (n++ < 100 && server.getActiveSessions().size() > 0) {
            Thread.sleep(100);
        }
        assertThat(server.getActiveSessions().size()).isEqualTo(0);
        f.destroy();
    }
}

@Test
void concurrentGetSessionDoesntCauseFailure() throws Exception {
    try (SshServer server = SshServer.setUpDefaultServer()) {
        server.setPasswordAuthenticator((arg0, arg1, arg2) -> true);
        server.setPort(0);
        server.setKeyPairProvider(new SimpleGeneratorHostKeyProvider(new File("hostkey.ser").toPath()));
        server.setSubsystemFactories(Collections.singletonList(new SftpSubsystemFactory()));
        server.start();
        DefaultSftpSessionFactory sftpSessionFactory = new DefaultSftpSessionFactory();
        sftpSessionFactory.setHost("localhost");
        sftpSessionFactory.setPort(server.getPort());
        sftpSessionFactory.setUser("user");
        sftpSessionFactory.setPassword("pass");
        sftpSessionFactory.setAllowUnknownKeys(true);
        List<CompletableFuture<SftpSession>> concurrentSessions = new ArrayList<>();
        try (var asyncTaskExecutor = new SimpleAsyncTaskExecutor()) {
            for (int i = 0; i < 3; i++) {
                concurrentSessions.add(asyncTaskExecutor.submitCompletable(sftpSessionFactory::getSession));
            }
        }
        assertThat(CompletableFuture.allOf(concurrentSessions.toArray(CompletableFuture[]::new))).succeedsWithin(Duration.ofSeconds(10));
        List<SftpSession> sftpSessions = concurrentSessions.stream().map(CompletableFuture::join).toList();
        assertThat(sftpSessions.get(0)).isNotEqualTo(sftpSessions.get(1)).isNotEqualTo(sftpSessions.get(2));
        assertThat(sftpSessions.get(1)).isNotEqualTo(sftpSessions.get(2));
        sftpSessionFactory.destroy();
    }
}

