    IntegrationFlow flow = IntegrationFlow.from(Smb.inboundAdapter(sessionFactory()).preserveTimestamp(true).remoteDirectory("smbSource/subSmbSource/").maxFetchSize(10).scanner(scanner).regexFilter(".*\\.txt$").localFilename(f -> f.toUpperCase() + ".a").localDirectory(getTargetLocalDirectory()), e -> e.id("smbInboundAdapter").poller(Pollers.fixedDelay(100))).channel(out).get();
    IntegrationFlowRegistration registration = this.flowContext.registration(flow).register();
