@Test
public void testClientWebSocketContainer() throws Exception {
    AtomicBoolean failure = new AtomicBoolean();
    StandardWebSocketClient webSocketClient = new StandardWebSocketClient() {

        @Override
        protected CompletableFuture<WebSocketSession> executeInternal(WebSocketHandler webSocketHandler, HttpHeaders headers, URI uri, List<String> protocols, List<WebSocketExtension> extensions, Map<String, Object> attributes) {
            CompletableFuture<WebSocketSession> future = super.executeInternal(webSocketHandler, headers, uri, protocols, extensions, attributes);
            if (failure.get()) {
                future.cancel(true);
            }
            return future;
        }
    };
    Map<String, Object> userProperties = new HashMap<>();
    userProperties.put(Constants.IO_TIMEOUT_MS_PROPERTY, "" + (Constants.IO_TIMEOUT_MS_DEFAULT * 6));
    webSocketClient.setUserProperties(userProperties);
    ClientWebSocketContainer container = new ClientWebSocketContainer(webSocketClient, new URI(server.getWsBaseUrl() + "/ws/websocket"));
    TestWebSocketListener messageListener = new TestWebSocketListener();
    container.setMessageListener(messageListener);
    container.setConnectionTimeout(30);
    container.start();
    WebSocketSession session = container.getSession(null);
    assertThat(session).isNotNull();
    assertThat(session.isOpen()).isTrue();
    assertThat(session.getAcceptedProtocol()).isEqualTo("v10.stomp");
    session.sendMessage(new PingMessage());
    assertThat(messageListener.messageLatch.await(10, TimeUnit.SECONDS)).isTrue();
    container.stop();
    assertThatIllegalStateException().isThrownBy(() -> container.getSession(null)).withMessage("'clientSession' has not been established. Consider to 'start' this container.");
    assertThat(messageListener.sessionEndedLatch.await(10, TimeUnit.SECONDS)).isTrue();
    assertThat(session.isOpen()).isFalse();
    assertThat(messageListener.started).isTrue();
    assertThat(messageListener.message).isInstanceOf(PongMessage.class);
    failure.set(true);
    assertThatIllegalStateException().isThrownBy(container::start).withCauseInstanceOf(CancellationException.class);
    failure.set(false);
    container.start();
    session = container.getSession(null);
    assertThat(session).isNotNull();
    assertThat(session.isOpen()).isTrue();
}

